solution:
for (let i = 0; i < 5; i++) {
  let stars = i < 3 ? 2*i+1 : 2*(4-i)+1;
  let spaces = ' '.repeat(2-Math.abs(i-2));
  console.log(spaces + '*'.repeat(stars));
